components.css:
.ds-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-family: var(--font-geist-sans, -apple-system, sans-serif);
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1;
  border-radius: 10px;
  border: 1px solid transparent;
  padding: 0 10px;
  height: 32px;
  cursor: pointer;
  white-space: nowrap;
  transition: background-color 150ms cubic-bezier(0.16, 1, 0.3, 1),
              color 150ms cubic-bezier(0.16, 1, 0.3, 1),
              opacity 150ms cubic-bezier(0.16, 1, 0.3, 1);
  outline: none;
}
.ds-btn:focus-visible {
  box-shadow: 0 0 0 3px oklch(0.72 0.15 145 / 0.5);
}
.ds-btn:disabled {
  opacity: 0.5;
  pointer-events: none;
}
.ds-btn--primary {
  background-color: oklch(0.985 0 0);
  color: oklch(0.205 0 0);
}
.ds-btn--primary:hover {
  background-color: oklch(0.955 0 0);
}
.ds-btn--primary:active {
  background-color: oklch(0.922 0 0);
}

.ds-btn--outline {
  background-color: transparent;
  color: oklch(0.985 0 0);
  border-color: oklch(0.985 0 0 / 0.2);
}
.ds-btn--outline:hover {
  background-color: oklch(0.985 0 0 / 0.08);
  border-color: oklch(0.985 0 0 / 0.4);
}

.ds-filter-pills {
  display: inline-flex;
  align-items: center;
  background-color: oklch(0.14 0 0 / 0.8);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-radius: 9999px;
  border: 1px solid oklch(1 0 0 / 0.10);
  padding: 3px;
  gap: 2px;
}
.ds-filter-pill {
  font-family: var(--font-geist-sans, -apple-system, sans-serif);
  font-size: 0.75rem;
  font-weight: 500;
  height: 26px;
  padding: 0 12px;
  border-radius: 9999px;
  border: none;
  background: transparent;
  color: oklch(0.708 0 0);
  cursor: pointer;
  transition: background-color 150ms, color 150ms;
  outline: none;
}
.ds-filter-pill:hover {
  color: oklch(0.985 0 0);
  background-color: oklch(0.985 0 0 / 0.06);
}
.ds-filter-pill--active {
  background-color: oklch(0.205 0 0);
  color: oklch(0.985 0 0);
}
.ds-filter-pill--active:hover {
  background-color: oklch(0.230 0 0);
}
.ds-filter-pill--disabled,
.ds-filter-pill:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  pointer-events: none;
}
.ds-filter-pill:focus-visible {
  box-shadow: 0 0 0 2px oklch(0.72 0.15 145 / 0.6);
}

.ds-search {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background-color: oklch(0.14 0 0 / 0.8);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-radius: 9999px;
  border: 1px solid oklch(1 0 0 / 0.10);
  padding: 0 12px;
  height: 32px;
  width: 144px;
  transition: width 200ms cubic-bezier(0.16, 1, 0.3, 1),
              border-color 150ms;
}
.ds-search:focus-within {
  width: 192px;
  border-color: oklch(1 0 0 / 0.2);
}
.ds-search__icon {
  color: oklch(0.556 0 0);
  flex-shrink: 0;
}
.ds-search__input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  font-family: var(--font-geist-sans, -apple-system, sans-serif);
  font-size: 0.875rem;
  color: oklch(0.985 0 0);
  min-width: 0;
}
.ds-search__input::placeholder {
  color: oklch(0.556 0 0);
}
.ds-search__clear {
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  cursor: pointer;
  color: oklch(0.556 0 0);
  padding: 2px;
  border-radius: 50%;
  transition: color 100ms;
}
.ds-search__clear:hover {
  color: oklch(0.985 0 0);
}

.ds-tooltip {
  position: absolute;
  pointer-events: none;
  background-color: oklch(0.205 0 0);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-radius: 16px;
  border: 1px solid oklch(1 0 0 / 0.08);
  box-shadow: 0 4px 30px oklch(0 0 0 / 0.5);
  padding: 14px 16px;
  min-width: 160px;
  max-width: 200px;
}
.ds-tooltip__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
}
.ds-tooltip__name {
  font-family: var(--font-geist-sans, -apple-system, sans-serif);
  font-size: 0.8125rem;
  font-weight: 600;
  color: oklch(0.985 0 0);
}
.ds-tooltip__badge {
  font-family: var(--font-geist-mono, monospace);
  font-size: 0.75rem;
  font-weight: 700;
}
.ds-tooltip__badge--up {
  color: oklch(0.63 0.22 27);
}
.ds-tooltip__badge--up-moderate {
  color: oklch(0.70 0.19 50);
}
.ds-tooltip__badge--stable {
  color: oklch(0.556 0 0);
}
.ds-tooltip__badge--down-moderate {
  color: oklch(0.72 0.18 127);
}
.ds-tooltip__badge--down {
  color: oklch(0.63 0.19 145);
}
.ds-tooltip__price {
  font-family: var(--font-geist-mono, monospace);
  font-size: 0.875rem;
  color: oklch(0.922 0 0);
  margin-bottom: 2px;
}
.ds-tooltip__price-value {
  font-weight: 600;
}
.ds-tooltip__unit {
  color: oklch(0.708 0 0);
  font-size: 0.75rem;
}
.ds-tooltip__timeframe {
  font-family: var(--font-geist-sans, -apple-system, sans-serif);
  font-size: 0.6875rem;
  color: oklch(0.556 0 0);
  margin-bottom: 10px;
}
.ds-tooltip__sparkline {
  display: block;
  opacity: 0.7;
}

.ds-data-footer {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 28px;
  padding: 0 16px;
  background-color: oklch(0.07 0 0 / 0.85);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  border-top: 1px solid oklch(1 0 0 / 0.05);
}
.ds-data-footer__item {
  display: flex;
  align-items: center;
  gap: 6px;
}
.ds-data-footer__label {
  font-family: var(--font-geist-sans, -apple-system, sans-serif);
  font-size: 0.6875rem;
  color: oklch(0.439 0 0);
}
.ds-data-footer__value {
  font-family: var(--font-geist-mono, monospace);
  font-size: 0.6875rem;
  font-weight: 500;
  color: oklch(0.708 0 0);
}

.ds-bubble-skeleton {
  position: absolute;
  inset: 0;
  overflow: hidden;
}
.ds-bubble-skeleton__svg {
  width: 100%;
  height: 100%;
}
.ds-bubble-skeleton__circle {
  fill: oklch(0.269 0 0);
  animation: ds-pulse 1.8s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}
.ds-bubble-skeleton__circle:nth-child(2n) {
  animation-delay: 0.15s;
}
.ds-bubble-skeleton__circle:nth-child(3n) {
  animation-delay: 0.30s;
}
@keyframes ds-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.45; }
}
@media (prefers-reduced-motion: reduce) {
  .ds-bubble-skeleton__circle {
    animation: none;
    opacity: 0.6;
  }
}

.ds-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  text-decoration: none;
}
.ds-logo__mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: linear-gradient(135deg, oklch(0.72 0.15 145) 0%, oklch(0.58 0.15 145) 100%);
  box-shadow: 0 0 15px oklch(0.70 0.17 145 / 0.5);
  font-family: var(--font-geist-sans, -apple-system, sans-serif);
  font-size: 1rem;
  font-weight: 700;
  color: oklch(0.985 0 0);
  letter-spacing: -0.02em;
}
.ds-logo__wordmark {
  font-family: var(--font-geist-sans, -apple-system, sans-serif);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: oklch(0.985 0 0);
}
